# prompts.py - picture prompts for glass-rain-planet (all gpt-image-2.5-sunburst, 1K, quality LOW, 1 variation, NO references)
# STYLE / CHARACTER / KEY / BG blocks word for word from memory/STYLE.md (the channel's locked look).
import json
CHAR = "Flat 2D cartoon: a simple white character with a big round head, a small soft body, noodle arms with simple four-finger hands and short legs with rounded feet, thick smooth black (#000000) outlines of even weight, about 2 % of the head width thick, flat white fill (#FEFDFD) with a very soft pale-grey shade (#EDEBEB) on the left side of the head and body, the round head is wider than the body and about 0.38 of the full body height, small solid black vertical oval eyes about one sixth of the head width tall, simple curved black eyebrows, no nose, no hair, no clothes, a pink tongue (#FC8D90) only when the mouth is open. Clean vector-like linework, flat colours, no texture, no text, no border."
SWIM0 = " This character is ready for a swim: exactly the same simple white character, wearing only small sky-blue swim goggles pushed up high on the forehead (the eyes stay uncovered) and a red-and-white striped inflatable swim ring around the waist - nothing else added, no hair, no clothes."  # hero prompt
# measured on the keyed hero: lenses #5ACBF6, frame + strap #1C7FBC, ring red #F1301D + white, outline ~1.8 % of the head width
SWIM = " This character is ready for a swim: exactly the same simple white character, wearing only small swim goggles with round light-blue (#5ACBF6) lenses and a darker blue (#1C7FBC) frame and strap, pushed up high on the forehead (the eyes stay uncovered), and a red (#F1301D) and white striped inflatable swim ring around the waist with about eight wide alternating stripes - nothing else added, no hair, no clothes."
OBJ = "Flat 2D cartoon in the same drawing style: bold clean thick smooth black outlines of even weight, flat colours with one simple soft shade, clean vector-like linework, simple shapes, no texture, no text, no border, no characters."
def KEY(c='green'):
    col = 'pure green (#00FF00)' if c == 'green' else 'pure magenta (#FF00FF)'
    return f"Isolated on a perfectly flat, uniform, solid {col} background that fills the whole picture edge to edge: no shadow, no ground, no floor line, no gradient, no vignette, no border, no other objects. The whole subject in frame with a clear margin on every side."
BG = "Flat 2D cartoon background in the same drawing style: big simple flat-colour shapes, thick smooth black outlines only on the main shapes, no texture, no text, no labels, no arrows, no characters, calm and simple so a character reads clearly on top of it."
THREE = "Three DIFFERENT poses of the same character side by side in one row, all three the same size, with wide empty gaps between them, every copy full body, bold clean thick outlines. "
TWO_CU = "Two DIFFERENT expressions of the same character side by side with a wide empty gap between them, both waist-up close-ups facing the viewer: only the head, the chest and the top of the swim ring are visible, the bottom edge of each copy is a straight cut at the waist. Bold clean thick outlines. "
tail = " Whole bodies in frame with a margin. " + CHAR + SWIM + " " + KEY()
P = {
 'hero': ("2:3", "Full body, facing the viewer, excited and ready to jump into water: knees slightly bent, both arms swung back behind the body, leaning forward a little, a big happy open-mouth smile with the pink tongue showing, eyebrows raised. Whole body in frame with a margin. Bold clean thick outlines. " + CHAR + SWIM0 + " " + KEY()),
 'jump3': ("3:2", THREE + "LEFT copy: standing on one leg, the other leg stretched out to the RIGHT side of the image with the toes pointed down as if testing the water, both arms held out to the sides for balance, curious face looking down to the right, small round open mouth. MIDDLE copy: jumping up high, both arms raised straight up, legs together, eyes closed, huge happy open-mouth smile with the pink tongue showing. RIGHT copy: cannonball pose in mid-air, knees pulled up to the chest and hugged with both arms, eyes squeezed shut, cheeks puffed out, mouth closed." + tail),
 'fall3': ("3:2", THREE + "LEFT copy: falling belly-down seen from the front, arms and legs spread wide like a starfish, looking down with a puzzled face, eyebrows raised, small open mouth. MIDDLE copy: falling feet first, holding its breath for a splash: the hand on the LEFT side of the image pinching the middle of the face as if holding a nose closed (no nose drawn), the other arm raised straight up, cheeks puffed, eyes squeezed shut. RIGHT copy: falling feet first, confused: the hand on the RIGHT side of the image scratching the top of the head, the other arm hanging down, looking down, eyebrows tilted, small wavy mouth." + tail),
 'shock3': ("3:2", THREE + "LEFT copy: shocked, both hands pressed on the cheeks, mouth wide open in a long vertical oval with the pink tongue showing, eyebrows raised high, wide eyes, knees together. MIDDLE copy: scared, both arms flailing up in the air, legs kicking, eyes wide, mouth wide open screaming with the pink tongue showing. RIGHT copy: smug and confident, the hand on the RIGHT side of the image raised above the head in a closed fist as if holding an umbrella handle (nothing in the hand), the other fist on the hip, smug closed-mouth smile, relaxed eyebrows." + tail),
 'wind3': ("3:2", THREE + "LEFT copy: leaning far over to the LEFT against a very strong wind, both arms crossed in front of the face like a shield, eyes squeezed shut, teeth gritted. MIDDLE copy: curled up into a tight ball, both arms wrapped around the knees, eyes squeezed shut, small wavy worried mouth. RIGHT copy: hanging from both raised hands that grip an invisible bar above the head (nothing drawn in the hands), the body and legs swinging out to the RIGHT at a steep angle, terrified face, eyebrows tilted up, mouth wide open." + tail),
 'nose2': ("3:2", TWO_CU + "LEFT copy: eyes closed, taking a big happy deep breath of fresh air, chest puffed out, chin lifted, a blissful closed-mouth smile, both hands on the chest. RIGHT copy: disgusted by a terrible smell, eyes squeezed shut, the pink tongue sticking out, mouth twisted, the hand on the LEFT side of the image pinching the middle of the face (no nose drawn), the other hand waving the air away. " + CHAR + SWIM + " " + KEY()),
 'ship': ("3:2", "One small cute cartoon spaceship seen from the side, facing RIGHT: a round chubby capsule body, white with one wide orange stripe around the middle, one big round porthole window on the front half with light-blue glass and a thick grey rim, a small square door on the left half, two little grey rocket nozzles at the back on the left, three short grey landing legs at the bottom, no flame, no smoke. Bold clean thick outlines. " + OBJ + " " + KEY()),
 'space': ("2:3", "Outer space, vertical picture: a deep dark-navy sky with a few small simple white four-point stars, a small orange sun in the upper left corner, and a huge round deep cobalt-blue gas planet in the bottom half: its round top edge at about 52 % of the picture height, as wide as the picture, with soft lighter-blue swirling cloud bands and a thin pale-blue glow along its edge. No rings, no moons, no ships, no people, no text. " + BG),
 'sky': ("2:3", "Inside the sky of a hot blue gas planet, vertical picture: no ground and no water anywhere, only endless sky in flat horizontal bands, light azure blue at the top getting deeper cobalt blue toward the bottom, a few long soft pale-blue haze streaks and some simple flat white-blue cloud puffs floating at different heights. No people, no text, no sun. " + BG),
 'extra3': ("3:2", THREE + "LEFT copy: crouching wind-up right before a big jump, knees deeply bent, both arms swung far back behind the body, leaning forward, excited open-mouth grin with the pink tongue showing. MIDDLE copy: a diver's pose, standing perfectly straight, both arms raised straight up together above the head with the palms pressed together, legs together, toes pointed, eyes closed, happy closed-mouth smile. RIGHT copy: frantically doggy-paddling in the air, facing the viewer, both arms paddling wildly in front of the chest, legs kicking, determined panicked face with wide eyes and gritted teeth." + tail),
}
json.dump(P, open('prompts.json', 'w'), indent=1)
with open('prompts.md', 'w') as f:
    f.write('# glass-rain-planet - picture prompts (all gpt-image-2.5-sunburst, 1K, quality LOW, 1 variation, no references)\n\n')
    for k, (ar, p) in P.items(): f.write(f'## {k} ({ar})\n{p}\n\n')
for k, (ar, p) in P.items(): print(k, ar, len(p))
